import { createServer } from "node:http";
import { readFile, writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { dirname, extname, join, normalize, sep } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = join(ROOT, "books.json");
const PUBLIC_DIR = join(ROOT, "public");
const PORT = process.env.PORT || 3000;

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
};

let books = [];
try {
  const parsed = JSON.parse(await readFile(DATA_FILE, "utf8"));
  if (Array.isArray(parsed)) books = parsed;
} catch {}

async function save() {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2) + "\n");
}

function send(res, status, body, type = "application/json; charset=utf-8") {
  res.writeHead(status, { "Content-Type": type });
  res.end(typeof body === "string" || Buffer.isBuffer(body) ? body : JSON.stringify(body));
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1e6) {
        reject(new Error("request body too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      try {
        resolve(data ? JSON.parse(data) : {});
      } catch {
        reject(new Error("invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

async function handleApi(req, res, path) {
  if (req.method === "GET" && path === "/api/books") {
    return send(res, 200, books);
  }

  if (req.method === "POST" && path === "/api/books") {
    const { title, author, notes } = await readBody(req);
    if (!String(title || "").trim() || !String(author || "").trim()) {
      return send(res, 400, { error: "title and author are required" });
    }
    const book = {
      id: randomUUID(),
      title: String(title).trim(),
      author: String(author).trim(),
      notes: String(notes || "").trim(),
      status: "reading",
      createdAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    await save();
    return send(res, 201, book);
  }

  const match = path.match(/^\/api\/books\/([0-9a-fA-F-]{1,64})$/);
  if (!match) return send(res, 404, { error: "not found" });

  const book = books.find((b) => b.id === match[1]);
  if (!book) return send(res, 404, { error: "book not found" });

  if (req.method === "GET") return send(res, 200, book);

  if (req.method === "PATCH") {
    const patch = await readBody(req);
    if (patch.status === "finished" || patch.status === "reading") {
      book.status = patch.status;
      book.finishedAt = book.status === "finished" ? new Date().toISOString() : null;
    }
    if (typeof patch.notes === "string") book.notes = patch.notes.trim();
    await save();
    return send(res, 200, book);
  }

  return send(res, 405, { error: "method not allowed" });
}

async function serveStatic(req, res, path) {
  if (req.method !== "GET" && req.method !== "HEAD") {
    return send(res, 405, { error: "method not allowed" });
  }
  const target = normalize(path === "/" ? "index.html" : path.slice(1));
  const file = join(PUBLIC_DIR, target);
  if (file === PUBLIC_DIR || !file.startsWith(PUBLIC_DIR + sep)) {
    return send(res, 403, { error: "forbidden" });
  }
  try {
    const data = await readFile(file);
    return send(res, 200, data, MIME[extname(file)] || "application/octet-stream");
  } catch {
    try {
      const index = await readFile(join(PUBLIC_DIR, "index.html"));
      return send(res, 200, index, MIME[".html"]);
    } catch {
      return send(res, 404, { error: "not found" });
    }
  }
}

const server = createServer(async (req, res) => {
  const path = new URL(req.url, "http://localhost").pathname;
  try {
    if (path.startsWith("/api/")) return await handleApi(req, res, path);
    return await serveStatic(req, res, path);
  } catch (err) {
    send(res, 400, { error: err.message });
  }
});

server.listen(PORT, () => {
  console.log(`bookshelf running at http://localhost:${PORT}`);
});

