:root {
  color-scheme: light dark;
  --text: #1f2328;
  --muted: #6e7781;
  --bg: #f6f5f1;
  --card: #ffffff;
  --border: #e0ddd5;
  --accent: #2f6f4f;
}
@media (prefers-color-scheme: dark) {
  :root {
    --text: #e6e3dc;
    --muted: #9a958b;
    --bg: #17161a;
    --card: #201f24;
    --border: #35333a;
    --accent: #7fbf9f;
  }
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font: 16px/1.5 system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
}
main { max-width: 620px; margin: 0 auto; padding: 32px 16px 80px; }
h1 { font-size: 1.6rem; margin: 0 0 16px; }
h2 {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin: 32px 0 8px;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
form, .book {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px 14px;
}
form { display: grid; gap: 8px; margin-bottom: 8px; }
input, textarea {
  font: inherit;
  color: inherit;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 10px;
  width: 100%;
}
input:focus, textarea:focus { outline: 2px solid var(--accent); outline-offset: -1px; }
button {
  font: inherit;
  cursor: pointer;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: transparent;
  color: inherit;
  padding: 6px 12px;
}
button:hover { border-color: var(--accent); color: var(--accent); }
form button[type="submit"] {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg);
  font-weight: 600;
  justify-self: start;
}
ul.books { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.book { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.book a { font-weight: 600; }
.author { color: var(--muted); }
.actions { display: flex; gap: 6px; flex-shrink: 0; }
.empty { color: var(--muted); font-style: italic; }
.badge {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 2px 10px;
  color: var(--muted);
  vertical-align: middle;
}
.badge.reading { border-color: var(--accent); color: var(--accent); }
.flash {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%) translateY(8px);
  background: var(--text);
  color: var(--bg);
  border-radius: 6px;
  padding: 8px 16px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
}
.flash.show { opacity: 1; transform: translateX(-50%) translateY(0); }

