const app = document.getElementById("app");
const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

async function api(path, opts) {
  const res = await fetch(path, { headers: { "Content-Type": "application/json" }, ...opts });
  const body = await res.json().catch(() => null);
  if (!res.ok) throw new Error(body?.error || `request failed (${res.status})`);
  return body;
}

function flash(message, isError = false) {
  document.querySelector(".flash")?.remove();
  const el = document.createElement("div");
  el.className = "flash show";
  el.style.background = isError ? "#a4342c" : "";
  el.textContent = message;
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 2500);
}

const go = (path) => {
  history.pushState(null, "", path);
  render();
};

document.addEventListener("click", (e) => {
  const link = e.target.closest("a[data-link]");
  if (link) {
    e.preventDefault();
    go(link.href);
  }
});

window.addEventListener("popstate", render);

function bookRow(book) {
  const done = book.status === "finished";
  return `
    <li class="book">
      <div>
        <a data-link href="/book/${book.id}">${esc(book.title)}</a>
        <span class="author"> — ${esc(book.author)}</span>
      </div>
      <div class="actions">
        ${done
          ? '<span class="badge">finished</span>'
          : `<button data-finish="${book.id}">Mark finished</button>`}
      </div>
    </li>`;
}

function renderList(books) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books.filter((b) => b.status === "finished");
  app.innerHTML = `
    <h1>Bookshelf</h1>
    <form id="add-form">
      <input name="title" placeholder="Title" required maxlength="200">
      <input name="author" placeholder="Author" required maxlength="200">
      <textarea name="notes" placeholder="Notes (optional)" rows="2" maxlength="5000"></textarea>
      <button type="submit">Add book</button>
    </form>
    <h2>Currently reading (${reading.length})</h2>
    ${reading.length ? `<ul class="books">${reading.map(bookRow).join("")}</ul>` : '<p class="empty">Nothing yet — add a book above.</p>'}
    <h2>Finished (${finished.length})</h2>
    ${finished.length ? `<ul class="books">${finished.map(bookRow).join("")}</ul>` : '<p class="empty">No finished books yet.</p>'}
  `;

  document.getElementById("add-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    const form = new FormData(e.target);
    try {
      await api("/api/books", { method: "POST", body: JSON.stringify(Object.fromEntries(form)) });
      flash("Book added");
      render();
    } catch (err) {
      flash(err.message, true);
    }
  });

  app.querySelectorAll("button[data-finish]").forEach((btn) =>
    btn.addEventListener("click", async () => {
      try {
        await api(`/api/books/${btn.dataset.finish}`, { method: "PATCH", body: JSON.stringify({ status: "finished" }) });
        flash("Marked finished");
        render();
      } catch (err) {
        flash(err.message, true);
      }
    })
  );
}

function renderDetail(book) {
  const done = book.status === "finished";
  app.innerHTML = `
    <p><a data-link href="/">← all books</a></p>
    <h1>${esc(book.title)} ${done ? '<span class="badge">finished</span>' : '<span class="badge reading">reading</span>'}</h1>
    <p class="author">by ${esc(book.author)}</p>
    <div class="actions" style="margin: 16px 0">
      ${done
        ? `<button data-restart="${book.id}">Mark as reading again</button>`
        : `<button data-finish="${book.id}">Mark finished</button>`}
      <button data-copy="${book.id}">Copy share link</button>
    </div>
    <h2>Notes</h2>
    <form id="notes-form">
      <textarea name="notes" rows="6" placeholder="Your notes…">${esc(book.notes)}</textarea>
      <button type="submit">Save notes</button>
    </form>
  `;

  const setStatus = async (status) => {
    try {
      await api(`/api/books/${book.id}`, { method: "PATCH", body: JSON.stringify({ status }) });
      render();
    } catch (err) {
      flash(err.message, true);
    }
  };
  app.querySelector("button[data-finish]")?.addEventListener("click", () => setStatus("finished"));
  app.querySelector("button[data-restart]")?.addEventListener("click", () => setStatus("reading"));
  app.querySelector("button[data-copy]").addEventListener("click", async () => {
    const url = `${location.origin}/book/${book.id}`;
    try {
      await navigator.clipboard.writeText(url);
      flash("Link copied");
    } catch {
      prompt("Copy this link:", url);
    }
  });
  document.getElementById("notes-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    try {
      await api(`/api/books/${book.id}`, { method: "PATCH", body: JSON.stringify({ notes: new FormData(e.target).get("notes") }) });
      flash("Notes saved");
    } catch (err) {
      flash(err.message, true);
    }
  });
}

async function render() {
  const detail = location.pathname.match(/^\/book\/([0-9a-fA-F-]{1,64})$/);
  try {
    if (detail) {
      const book = await api(`/api/books/${detail[1]}`);
      document.title = `${book.title} — Bookshelf`;
      renderDetail(book);
    } else {
      const books = await api("/api/books");
      document.title = "Bookshelf";
      renderList(books);
    }
  } catch (err) {
    app.innerHTML = `<h1>Book not found</h1><p><a data-link href="/">← all books</a></p>`;
    if (!detail) flash(err.message, true);
  }
}

render();

